  const params = {};
  const queryStartIndex = url.indexOf('?');

  if (queryStartIndex === -1 || queryStartIndex === url.length - 1) {
    return params;
  }

  const queryString = url.substring(queryStartIndex + 1);
  const paramPairs = queryString.split('&');

  for (let i = 0; i < paramPairs.length; i++) {
    const pair = paramPairs[i];
    const eqIndex = pair.indexOf('=');

    if (eqIndex !== -1 && eqIndex !== 0) {
      const key = decodeURIComponent(pair.substring(0, eqIndex));
      const value = decodeURIComponent(pair.substring(eqIndex + 1));
      if (key !== '') { // Ensure key is not an empty string
        params[key] = value;
      }
    } else if (eqIndex === -1 && pair !== '') { // Handle parameters without values, like "param"
      params[decodeURIComponent(pair)] = '';
    }
  }

  return params;
}

